// Name is the module name and permission prefix.
const Name = "notice"

// Deps are the module's dependencies.
type Deps struct {
	DB *gorm.DB
	// Dict checks dictionary-backed fields (the system module implements
	// it); nil skips the check.
	Dict DictLookup
}

// Module is the 消息中心 module.
type Module struct {
	db   *gorm.DB
	dict DictLookup
}

var _ module.Module = (*Module)(nil)

// New creates the module.
func New(deps Deps) *Module {
	return &Module{db: deps.DB, dict: deps.Dict}
}

